 "content": "def transform(grid):
    """Repeat a 3x3 pattern as a 3x3 tiling with horizontal reflection."""
    n = len(grid)
    if not n or any(len(row) != n for row in grid):
        raise ValueError("expected a non-empty square grid")
    out = []
    for tile_row in range(3):
        for r in range(n):
            source_r = r if tile_row == 1 else n - 1 - r
            row = grid[source_r]
            out.append(row[::-1] + row + row[::-1])
    return out
